    int lines = 0;
    int words = 0;
    long bytes = 0;
    long maxlen = 0;
    int inword = 0;
    char buf[65536];
    char *p = buf;
    size_t n = 0;
    int c;

    while ((c = fgetc(stdin)) != EOF) {
        bytes++;
        if (c == '\n') {
            lines++;
            if (n > maxlen) maxlen = n;
            n = 0;
