                words++;
                inword = 0;
            }
            n = 0;
        } else {
            n++;
            inword = 1;
        }
        *p++ = c;
        if (p - buf >= sizeof(buf)) {
            fwrite(buf, 1, sizeof(buf), stdout);
            p = buf;
        }
    }
    if (n > maxlen) maxlen = n;
    words += inword;
    printf("%d %d %ld %ld\n", lines, words, bytes, maxlen);
    return 0;
}

